using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public class SummarizePrompt
{
    [McpServerPrompt(Name = "summarize"), Description("Generates a prompt that asks for a summary of the given text.")]
    public static IEnumerable<PromptMessage> Summarize(
        [Description("The text to summarize")] string text,
        [Description("Desired summary style: brief, detailed, or bullet-points")] string style = "brief")
    {
        yield return new PromptMessage
        {
            Role = Role.User,
            Content = new Content
            {
                Type = "text",
                Text = $"Please provide a {style} summary of the following text:\n\n{text}"
            }
        };
    }
}

